D.battlegrounds[1]={n="Alterac Valley",lo=51,hi=60,ts=40,k="Epic battleground",win="Kill the enemy general",how={"40 against 40 in the Alterac Mountains: push down the valley, take graveyards and burn towers on the way.","Towers and graveyards are assaulted at their flag and fall a few minutes later unless retaken.","Kill the enemy general (Vanndar Stormpike in Dun Baldar or Drek'Thar in Frostwolf Keep) to win."},ob={"Irondeep Mine","Stonehearth Outpost","Iceblood Garrison","Coldtooth Mine","Frostwolf Keep","Stormpike Graveyard","Snowfall Graveyard","Frostwolf Graveyard","Dun Baldar South Bunker","Dun Baldar North Bunker","Icewing Bunker","Iceblood Tower","Tower Point","East Frostwolf Tower","Dun Baldar","Stonehearth Bunker","Stormpike Aid Station","Iceblood Graveyard","Stonehearth Graveyard","Frostwolf Relief Hut","West Frostwolf Tower","Wildpaw Cavern","Icewing Cavern"},rs="classic",rn="Rules are Classic's: Speculation until Forever's are known.",ui=1459,d="Hidden within the Alterac Mountains, Alterac Valley is the home of Thrall's own clan of orcs, the Frostwolves. The Stormpike dwarves have established a foothold in the valley and seek to plumb its depths for riches, and links to their ancestral past. The territorial Frostwolves, unwilling to suffer the dwarven incursion, have rallied an army... an army eager for righteous slaughter.",slug="alterac-valley"}
D.battlegrounds[2]={n="Warsong Gulch",lo=10,hi=60,ts=10,k="Capture the flag",win="Capture the enemy flag 3 times",how={"Take the enemy flag from their base and bring it to your own flag room while your flag is home.","Your flag must be at your base to score: kill their carrier to return it.","The scoreboard and the top of the screen show each team's captures."},rs="classic",rn="Rules are Classic's: Speculation until Forever's are known.",ui=1460,d="A valley bordering Ashenvale Forest and the Barrens, Warsong Gulch hosts a constant battle between the Horde and the Alliance. Orcs use their Warsong Mill to cut lumber reaped from Ashenvale, provoking the night elves of Silverwing Hold. Eager to aid their allies, members of every race in Azeroth rush to the Gulch to lend sword, or spell, to the conflict.",slug="warsong-gulch"}
D.battlegrounds[3]={n="Arathi Basin",lo=20,hi=60,ts=15,k="Capture points",win="First team to 2000 resources",cs=60,how={"Five bases (Stables, Blacksmith, Lumber Mill, Gold Mine, Farm) give resources while your team holds them: the more you hold, the faster you gain.","Click a base's flag to assault it; it becomes yours about a minute later unless the other team clicks it back.","Holding three bases usually wins."},ob={"Stables","Blacksmith","Lumber Mill","Gold Mine","Farm"},rs="classic",rn="Rules are Classic's: Speculation until Forever's are known.",ui=1461,d="The Arathi Basin is one of the main staging points of war between the Humans and the Forsaken in Azeroth. The League of Arathor seek to reclaim lost lands for their benefactors in Stormwind, while the Defilers – elite troopers under the watchful eye of Varimathras – seek to sever the vital connection between the Humans and their Dwarven allies to the south.",slug="arathi-basin"}
